import{_ as l,l as r,o as e,c as A,v as o,p as n,x as t,d as E,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"学校选择","description":"","frontmatter":{"title":"学校选择","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/school-choice.md","filePath":"econ/school-choice.md","lastUpdated":1789023840000}'),s={name:"econ/school-choice.md"};function c(p,a,m,D,u,T){const i=r("Mermaid");return e(),A("div",null,[a[1]||(a[1]=o('<h1 id="学校选择" tabindex="-1">学校选择 <a class="header-anchor" href="#学校选择" aria-label="Permalink to &quot;学校选择&quot;">​</a></h1><div class="epigraph"><p>学校有的是法定优先权，不是自身福利；波士顿即时接受可操纵，学生求婚延迟接受把诚实变成占优，纽约与波士顿的改革按此换算法。</p><footer>—— Abdulkadiroğlu and Sönmez, School Choice: A Mechanism Design Approach, American Economic Review, 2003；Abdulkadiroğlu, Pathak and Roth, The New York City High School Match, American Economic Review P&amp;P, 2005</footer></div><p><a href="/econ/many-to-one-matching">上一课</a>把医院写成有偏好、有名额的一方。缺口是公立学校：座位是公共资源，学校通常<strong>不</strong>最大化「分到哪些学生」的私利，只有法律与政策写成的优先权（步行区、兄姐、考试档）。学生有真偏好。此时「稳定」要对优先权来定义，机制选的是学生激励与公正，不是医院最优。本课钉学校选择，不重写农村医院，也不把显示原理的货币转移搬进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>学生报志愿，每校有名额与优先序。波士顿机制（即时接受）：第一志愿先录满，落空者进第二志愿——但第二志愿学校可能已被第一志愿学生占满。最优反应是把「录取概率高的安全校」报在前面，真话不是占优。Abdulkadiroğlu–Sönmez 把可选机制收成三件：波士顿、学生求婚 DA、Gale 的 TTC（顶层交易循环）。</p><p>学生求婚 DA：按真名单从上到下申请，学校按优先序暂持，拒绝后再向下。对学生策略证明；相对优先权稳定（没有学生与学校互相打破：学生更想去、学校按优先序也更该收他）。TTC：学生指向最想去的学校，学校指向优先序最高的学生，沿循环换「权利」，帕累托有效对学生，但不稳定（可牺牲优先权）。</p><h3 id="优先权不是学院偏好" tabindex="-1">优先权不是学院偏好 <a class="header-anchor" href="#优先权不是学院偏好" aria-label="Permalink to &quot;优先权不是学院偏好&quot;">​</a></h3><p>医院课里两边都有福利，稳定是核。学校选择里学校没有要最大化的支付，优先序是规范约束（谁更有权坐这个位）。「稳定」读成：不违反优先权地抢座位。政策可以故意放弃稳定，换学生端的效率（TTC）或透明度。</p><p><span class="marginnote">Abdulkadiroğlu–Pathak–Roth 记录纽约市高中与波士顿小学的换算法：从可操纵的即时代替到学生求婚 DA。Pathak–Sönmez 后来比较各城「可操纵程度」。本课只钉机制比较，不写学区政治过程。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：严格学生偏好、学校优先序、配额、无货币。先给波士顿一个三人教具：真实第一志愿热门、第二安全，诚实反而进更差的学校。再证 DA 对学生占优策略诚实（沿用上一课求婚方定理，学校当接收方、优先序当「偏好」）。最后对照 TTC：有效但可阻塞优先权。</p>',11)),(e(),n(d,null,{default:t(()=>[h(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOSP%5B%22%E5%8C%BB%E9%99%A2%EF%BC%9A%E4%B8%A4%E8%BE%B9%E6%9C%89%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20SC%5B%22%E5%AD%A6%E6%A0%A1%EF%BC%9A%E4%BC%98%E5%85%88%E6%9D%83%20%2B%20%E5%AD%A6%E7%94%9F%E5%81%8F%E5%A5%BD%22%5D%0A%20%20BOS%5B%22%E6%B3%A2%E5%A3%AB%E9%A1%BF%E5%8D%B3%E6%97%B6%E6%8E%A5%E5%8F%97%22%5D%20--%3E%20MAN%5B%22%E5%AD%A6%E7%94%9F%E7%AD%96%E7%95%A5%E6%80%A7%E5%A1%AB%E5%BF%97%E6%84%BF%22%5D%0A%20%20DA%5B%22%E5%AD%A6%E7%94%9F%E6%B1%82%E5%A9%9A%20DA%22%5D%20--%3E%20SP%5B%22%E5%AF%B9%E5%AD%A6%E7%94%9F%E7%AD%96%E7%95%A5%E8%AF%81%E6%98%8E%E3%80%81%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20TTC%5B%22TTC%22%5D%20--%3E%20EFF%5B%22%E5%AD%A6%E7%94%9F%E7%AB%AF%E6%9C%89%E6%95%88%E3%80%81%E4%B8%8D%E7%A8%B3%E5%AE%9A%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>政策选 DA 还是 TTC，是在「尊重优先权」与「学生帕累托」之间取舍，不是算法快慢。波士顿即时接受两项都差：既可操纵，又不必有效。</p><p>没有一边是「学校福利最优」需要保护；设计者选 DA 是为了学生诚实与优先权，选 TTC 是为了学生帕累托。稳定在学校选择里常叫「无正当嫉妒」：不存在学生 \\(i\\) 更想去学校 \\(s\\)，且 \\(i\\) 的优先序高于某个被 \\(s\\) 录取的学生。DA 消掉正当嫉妒；波士顿与 TTC 一般不能。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>即时接受把「第 \\(k\\) 志愿」变成劣质权利：学校在第 \\(k\\) 轮才看你时，位子可能已没。于是名单的排序本身成为稀缺品，家庭为信息与胆识付租金——与占优策略设计相反。DA 把申请变成「按真顺序消耗拒绝」，与住院医师医生求婚同一逻辑；学校一侧的「操纵」若只是行政优先序、不能谎报，则双边不可能定理的接收方问题被政策关掉。</p><p>TTC 把座位当可交易的权利，循环清掉帕累托改进，但会让高优先权学生被循环到低志愿、低优先权学生占热门校——稳定失败。是否可接受，是公正观，不是激励理论单独决定。</p><h3 id="大规模与近似诚实" tabindex="-1">大规模与近似诚实 <a class="header-anchor" href="#大规模与近似诚实" aria-label="Permalink to &quot;大规模与近似诚实&quot;">​</a></h3><p>偏好足够随机、市场足够大时，波士顿里一个人的操纵收益可以变小，但「该不该诚实」仍依赖别人怎么填；DA 的占优不依赖。这是选算法的理由，不是极限定理取消波士顿的操纵。</p><p><span class="marginnote">兄姐优先、步行区、多校联盟、转学中途插入，会破坏光秃 DA 的策略证明。合同匹配与名额预留是后继修补，本课只钉「优先权 vs 偏好」这一层。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>考试分数既当偏好又当优先，会回到双边都有排序的医院模型。私立学校有自身偏好，不是本课。也不要把志愿填报写成限价簿。货币学费若进入，机制变成带转移的匹配，AGV / VCG 那一套才重新有接口。</p><p>波士顿改革把「即时接受」换成 DA，不是因为计算更快，而是把诚实变成占优，降低对信息与胆识的租金。纽约高中匹配同期换算法，证据写在 Abdulkadiroğlu–Pathak–Roth 的田野记录里，不是新的存在性定理。</p><p>后课默认：学校选择用优先权代替机构福利；学生求婚 DA 对学生策略证明且稳定，波士顿可操纵，TTC 有效但不稳定。信息课序下一支从柠檬另起，不再填志愿。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>医院有偏好；公立学校通常只有优先权。</li><li>波士顿即时接受逼学生策略性填报。</li><li>学生求婚 DA：诚实占优，尊重优先权稳定。</li><li>TTC 对学生有效，可牺牲优先权。</li><li>出处：Abdulkadiroğlu and Sönmez, <em>AER</em>, 2003；Abdulkadiroğlu, Pathak and Roth, <em>AER</em> P&amp;P, 2005。</li></ul>',14))])}const C=l(s,[["render",c]]);export{_ as __pageData,C as default};
